export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  if (!row) return null;
  const subscription = getDb()
    .select({ plan: subscriptions.plan })
    .from(subscriptions)
    .where(eq(subscriptions.orgId, orgId))
    .get();
  return toOrganization({ ...row, plan: subscription?.plan ?? row.plan });
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (!row) return null;
  const subscription = getDb()
    .select({ plan: subscriptions.plan })
    .from(subscriptions)
    .where(eq(subscriptions.orgId, row.id))
    .get();
  return toOrganization({ ...row, plan: subscription?.plan ?? row.plan });
}

