export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => {
    const subscription = getDb()
      .select({ plan: subscriptions.plan })
      .from(subscriptions)
      .where(eq(subscriptions.orgId, row.org.id))
      .get();
    return toOrganization({ ...row.org, plan: subscription?.plan ?? row.org.plan });
  });
}
